#!/usr/bin/env node
// Generate static ad banners on fal (GPT Image 2), at every shape a placement needs.
//
//   node _scripts/banner-generate.mjs --prompts banner-prompts-b13-1lookup.mjs --dry
//   node _scripts/banner-generate.mjs --prompts banner-prompts-b13-1lookup.mjs
//   node _scripts/banner-generate.mjs --prompts ... --only 1lookup-skip-trace-c01
//   node _scripts/banner-generate.mjs --prompts ... --shapes square,vertical
//
// The banner batches before this one were generated by hand, one curl at a time, and the
// same three mistakes recurred across them. All three are now handled here rather than in
// a document:
//
//   1. NEITHER non-square delivery size can be generated directly. fal requires both
//      dimensions to be a multiple of 16, and 1200x628 (Meta link) and 1080x1920 (Stories)
//      are not. Landscape is the known case; vertical is the one that bites silently,
//      because fal accepts width 1080 and quietly returns 1072, shipping a 0.5583 aspect
//      where Stories wants 0.5625. So: generate at a legal size, then resize to the
//      delivery size, then ASSERT the delivered pixels. A file that is not exactly the
//      delivery size never lands.
//   2. Prompts get rendered before anyone re-reads the claim rules. `banner-prompt-lint.mjs`
//      runs inside this script, so a prompt that would fabricate a feature chip or open on
//      a disclaimer cannot spend money. --force overrides, noisily.
//   3. Nobody could tell later which file came from which prompt. Every run writes
//      `banner-run-log-<batch>.json` with the prompt, size, cost and sha of every file.
//
// Cost: about $0.20 per image at quality "high" (fal, 2026-08). A 40-image batch is ~$8,
// which is why concept count has never been the constraint on these batches.

import { mkdir, writeFile, readFile } from "node:fs/promises";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { statSync } from "node:fs";
import path from "node:path";

const KEY = process.env.FAL_KEY;
const ROOT = path.resolve(import.meta.dirname, "..");
const MODEL = "openai/gpt-image-2";
const COST_PER_IMAGE = 0.2;

const argv = process.argv.slice(2);
const flag = (n, d) => { const i = argv.indexOf(`--${n}`); return i === -1 ? d : argv[i + 1]; };
const has = (n) => argv.includes(`--${n}`);

const DRY = has("dry");
const ONLY = flag("only", null);
const PROMPTS = flag("prompts", null);
const CONCURRENCY = Number(flag("concurrency", "4"));
const SHAPES = (flag("shapes", "") || "").split(",").filter(Boolean);

if (!PROMPTS) throw new Error("--prompts <file in _scripts/> is required");
if (!KEY && !DRY) throw new Error("FAL_KEY is not set");

const mod = await import(`./${PROMPTS}`);
const BANNERS = mod.BANNERS ?? [];
const BATCH = mod.BATCH ?? flag("batch", null);
if (!BATCH) throw new Error("the prompts module must export BATCH (the dated folder name)");

// Shape table. `gen` is what we ask fal for (both dimensions divisible by 16); `out` is what
// the placement actually wants and what the file on disk must measure.
const SHAPE_SPEC = {
  square:    { gen: [1024, 1024], out: [1024, 1024], use: "Meta feed 1:1, Reddit feed, Google Display square" },
  landscape: { gen: [1200, 624],  out: [1200, 628],  use: "Meta link ad 1.91:1, Google Display landscape" },
  vertical:  { gen: [1088, 1920], out: [1080, 1920], use: "Stories, Reels, TikTok 9:16" },
  wide:      { gen: [1200, 320],  out: [1200, 300],  use: "Google Display leaderboard-ish 4:1" },
};

const log = (...a) => console.log(`[${new Date().toISOString().slice(11, 19)}]`, ...a);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ---------------------------------------------------------------- claim gate
// The lint is the gate, not a suggestion: it is the only thing standing between a bad
// prompt and real money, and every rule inside it exists because a batch already broke it.
if (!DRY) {
  try {
    execFileSync("node", [path.join(ROOT, "_scripts", "banner-prompt-lint.mjs"), path.join("_scripts", PROMPTS)], {
      cwd: ROOT, stdio: "inherit",
    });
  } catch {
    if (!has("force")) {
      console.error("\nRefusing to spend. Fix the prompts above, or pass --force.\n");
      process.exit(1);
    }
    log("--force: rendering prompts that failed the claim lint");
  }
}

// ---------------------------------------------------------------- resize + assert
// PIL rather than sharp: this environment has no native image module, and a wrong-sized
// file is the failure we are trying to make impossible, so the check has to actually run.
function resizeAndAssert(file, [w, h]) {
  const py = `
from PIL import Image
im = Image.open(${JSON.stringify(file)})
if im.size != (${w}, ${h}):
    im = im.convert("RGBA").resize((${w}, ${h}), Image.LANCZOS)
    im.save(${JSON.stringify(file)})
im = Image.open(${JSON.stringify(file)})
assert im.size == (${w}, ${h}), f"delivered {im.size}, wanted (${w}, ${h})"
print(f"{im.size[0]}x{im.size[1]}")
`;
  return execFileSync("python3", ["-c", py], { encoding: "utf8" }).trim();
}

async function submit(prompt, [w, h], label) {
  const res = await fetch(`https://queue.fal.run/${MODEL}`, {
    method: "POST",
    headers: { Authorization: `Key ${KEY}`, "Content-Type": "application/json" },
    body: JSON.stringify({ prompt, quality: "high", image_size: { width: w, height: h }, output_format: "png" }),
  });
  if (!res.ok) throw new Error(`${label} submit ${res.status}: ${(await res.text()).slice(0, 300)}`);
  const { status_url, response_url, request_id } = await res.json();
  log(`${label} queued ${request_id}`);

  for (let i = 0; i < 120; i++) {
    await sleep(4000);
    const s = await fetch(status_url, { headers: { Authorization: `Key ${KEY}` } });
    if (!s.ok) continue;
    const st = await s.json();
    if (st.status === "COMPLETED") {
      const r = await fetch(response_url, { headers: { Authorization: `Key ${KEY}` } });
      if (!r.ok) throw new Error(`${label} result ${r.status}`);
      return r.json();
    }
    if (st.status === "FAILED" || st.status === "ERROR") {
      throw new Error(`${label} FAILED: ${JSON.stringify(st).slice(0, 500)}`);
    }
  }
  throw new Error(`${label} timed out`);
}

async function pool(items, limit, fn) {
  const out = new Array(items.length);
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (next < items.length) {
      const i = next++;
      try { out[i] = { status: "fulfilled", value: await fn(items[i]) }; }
      catch (e) { out[i] = { status: "rejected", reason: e, item: items[i] }; }
    }
  }));
  return out;
}

// ---------------------------------------------------------------- build the job list
// {{SHAPE_WORD}} names the shape in the model's own vocabulary ("wide landscape"), and
// {{COMPOSITION}} tells it where to put things. Both are per-shape, so both are substituted
// here rather than baked into the prompt module.
const SHAPE_WORD = {
  square: "square",
  landscape: "wide landscape",
  vertical: "tall vertical",
  wide: "very wide short",
};

const COMPOSITION = {
  square: "Balanced centered square composition.",
  landscape: "Wide landscape composition with the text on the left and the visual element on the right.",
  vertical: "Tall vertical composition, the headline in the upper third, the visual element centered, the button in the lower third.",
  wide: "Very wide short banner, headline left, button right, visual element behind.",
};

const jobs = [];
for (const b of BANNERS) {
  if (ONLY && b.id !== ONLY) continue;
  for (const shape of b.shapes ?? ["square", "landscape"]) {
    if (SHAPES.length && !SHAPES.includes(shape)) continue;
    const spec = SHAPE_SPEC[shape];
    if (!spec) throw new Error(`${b.id}: unknown shape "${shape}"`);
    jobs.push({
      banner: b,
      shape,
      spec,
      // The shape hint goes at the front, where the model weights composition, while the
      // no-other-text constraint stays at the very end, which is the only place it holds.
      prompt: b.prompt
        .replace(/\{\{SHAPE_WORD\}\}/g, SHAPE_WORD[shape])
        .replace(/\{\{COMPOSITION\}\}/g, spec.composition ?? COMPOSITION[shape]),
      file: path.join(ROOT, b.company, BATCH, `${b.id}-${shape}.png`),
    });
  }
}

log(`${jobs.length} image(s) across ${new Set(jobs.map((j) => j.banner.id)).size} concept(s) · est $${(jobs.length * COST_PER_IMAGE).toFixed(2)}`);

if (DRY) {
  for (const j of jobs) {
    console.log(`\n--- ${path.relative(ROOT, j.file)}  gen ${j.spec.gen.join("x")} -> out ${j.spec.out.join("x")}  (${j.spec.use})`);
    console.log(j.prompt);
  }
  console.log(`\nDRY RUN: nothing generated, nothing spent.`);
  process.exit(0);
}

// ---------------------------------------------------------------- run
const results = await pool(jobs, CONCURRENCY, async (j) => {
  await mkdir(path.dirname(j.file), { recursive: true });
  const label = `${j.banner.id}-${j.shape}`;
  const out = await submit(j.prompt, j.spec.gen, label);
  const url = out.images?.[0]?.url ?? out.image?.url;
  if (!url) throw new Error(`${label}: no image url in ${JSON.stringify(out).slice(0, 300)}`);
  const bytes = Buffer.from(await (await fetch(url)).arrayBuffer());
  await writeFile(j.file, bytes);
  const delivered = resizeAndAssert(j.file, j.spec.out);
  const sha = createHash("sha256").update(await readFile(j.file)).digest("hex").slice(0, 12);
  log(`${label} -> ${path.relative(ROOT, j.file)} ${delivered} ${(statSync(j.file).size / 1024).toFixed(0)}KB`);
  return {
    id: j.banner.id, shape: j.shape, product: j.banner.product ?? null, concept: j.banner.concept ?? null,
    file: path.relative(ROOT, j.file), generated: j.spec.gen.join("x"), delivered, sha256: sha, prompt: j.prompt,
  };
});

const ok = results.filter((r) => r.status === "fulfilled").map((r) => r.value);
const bad = results.filter((r) => r.status === "rejected");

await writeFile(
  path.join(ROOT, "_scripts", `banner-run-log-${BATCH}.json`),
  JSON.stringify({
    ranAt: new Date().toISOString(),
    model: MODEL,
    batch: BATCH,
    estimatedSpendUsd: Number((jobs.length * COST_PER_IMAGE).toFixed(2)),
    ok,
    failed: bad.map((b) => ({ id: b.item?.banner?.id, shape: b.item?.shape, error: String(b.reason).slice(0, 400) })),
  }, null, 2),
);

log(`done · ${ok.length} ok · ${bad.length} failed · ~$${(jobs.length * COST_PER_IMAGE).toFixed(2)}`);
for (const b of bad) console.error("FAILED:", b.item?.banner?.id, b.item?.shape, String(b.reason).slice(0, 300));
if (bad.length) process.exitCode = 1;
